import { HTTPController, HTTPMethod, HTTPMethodEnum, HTTPBody, Inject } from 'egg';
import { Type, Static } from 'typebox';
import Ajv from 'ajv';

const CreateUserSchema = Type.Object({
  name: Type.String({ maxLength: 50 }),
  email: Type.String({ format: 'email' }),
});

type CreateUserParams = Static<typeof CreateUserSchema>;

const ajv = new Ajv();

@HTTPController({ path: '/api/users' })
export class UserController {
  @HTTPMethod({ method: HTTPMethodEnum.POST, path: '/' })
  async create(@HTTPBody() body: CreateUserParams) {
    const valid = ajv.validate(CreateUserSchema, body);
    if (!valid) throw new Error('Validation failed');
    return { id: '1', ...body };
  }
}

