import type { Context, Next } from 'egg';

export async function logMw(ctx: Context, next: Next): Promise<void> {
  const start = Date.now();
  await next();
  ctx.logger.info('request %s %s cost %dms', ctx.method, ctx.url, Date.now() - start);
}

import { Advice, IAdvice, AdviceContext } from 'egg/aop';

@Advice()
export class RequestCountAdvice implements IAdvice {
  private requestId = '';

  async around(ctx: AdviceContext, next: () => Promise<any>): Promise<any> {
    this.requestId = Math.random().toString(36).slice(2);
    const result = await next();
    return { ...result, requestId: this.requestId };
  }
}

import { HTTPController, HTTPMethod, HTTPMethodEnum, Middleware } from 'egg';
